     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	/** A report over the reservations that start in a month. */
    14	abstract class MonthlyReport implements Report {
    15	    @Override
    16	    public final String parameter() {
    17	        return "month";
    18	    }
    19	
    20	    @Override
    21	    public final ReportTable generate(String period, Tx tx) {
    22	        YearMonth month;
    23	        try {
    24	            month = YearMonth.parse(period);
    25	        } catch (DateTimeParseException e) {
    26	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "month must be formatted as yyyy-MM");
    27	        }
    28	        return build(month, tx);
    29	    }
    30	
    31	    protected abstract ReportTable build(YearMonth month, Tx tx);
    32	
    33	    /** Reservations starting in the month, by check-in date and then number. */
    34	    protected static List<Reservation> startingIn(YearMonth month, Tx tx) {
    35	        return tx.reservationsCheckingInBetween(month.atDay(1), month.plusMonths(1).atDay(1)).stream()
    36	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    37	                .toList();
    38	    }
    39	
    40	    /** Starting in the month and currently in a paid state (confirmed, checked in, checked out). */
    41	    protected static List<Reservation> paidStartingIn(YearMonth month, Tx tx) {
    42	        return startingIn(month, tx).stream().filter(Reservation::paid).toList();
    43	    }
    44	
    45	    /** Starting in the month and leaving money with the inn (paid minus refunded is positive). */
    46	    protected static List<Reservation> retainedStartingIn(YearMonth month, Tx tx) {
    47	        return startingIn(month, tx).stream().filter(r -> r.retained().signum() > 0).toList();
    48	    }
    49	}
