     9	public final class Money {
    10	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    11	
    12	    private Money() {
    13	    }
    14	
    15	    /** Every amount is rounded to cents, half to even, at each step. */
    16	    public static BigDecimal round(BigDecimal value) {
    17	        return value.setScale(2, RoundingMode.HALF_EVEN);
    18	    }
    19	
    20	    /** "R$ 1.234,56" */
    21	    public static String brl(BigDecimal value) {
    22	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    23	        symbols.setDecimalSeparator(',');
    24	        symbols.setGroupingSeparator('.');
    25	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(round(value));
    26	    }
    27	
    28	    /** "1234.56", as used in the CSV reports. */
    29	    public static String plain(BigDecimal value) {
    30	        return round(value).toPlainString();
    31	    }
    32	}
