     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     8	
     9	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    10	        BigDecimal subtotal = Money.ZERO;
    11	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    12	            subtotal = subtotal.add(nightPrice(room, night));
    13	        }
    14	        subtotal = Money.round(subtotal);
    15	        BigDecimal discount = plan.discountOn(subtotal);
    16	        return new Quote((int) ChronoUnit.DAYS.between(checkIn, checkOut), subtotal, discount,
    17	                Money.round(subtotal.subtract(discount)));
    18	    }
    19	
    20	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    21	        BigDecimal rate = room.nightlyRate();
    22	        if (Season.isHigh(night)) {
    23	            rate = rate.multiply(Season.HIGH_SEASON_MULTIPLIER);
    24	        }
    25	        return Money.round(rate);
    26	    }
    27	}
