     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	import static br.com.marealta.domain.ReservationStatus.*;
     7	
     8	public record Reservation(
     9	        long id,
    10	        int roomNumber,
    11	        String guestName,
    12	        String guestEmail,
    13	        String guestCpf,
    14	        LocalDate checkIn,
    15	        LocalDate checkOut,
    16	        int guests,
    17	        RatePlan ratePlan,
    18	        int nights,
    19	        BigDecimal subtotal,
    20	        BigDecimal discount,
    21	        BigDecimal total,
    22	        ReservationStatus status,
    23	        BigDecimal amountPaid,
    24	        BigDecimal refund) {
    25	
    26	    /** Confirmed, checked in or checked out: the guest has paid. */
    27	    public boolean paid() {
    28	        return status == CONFIRMED || status == CHECKED_IN || status == CHECKED_OUT;
    29	    }
    30	
    31	    /** Whether the reservation holds its room (everything but cancelled). */
    32	    public boolean holdsRoom() {
    33	        return status != CANCELLED;
    34	    }
    35	
    36	    /** Money that stays with the inn: paid minus refunded. */
    37	    public BigDecimal retained() {
    38	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    39	    }
    40	
    41	    public Reservation confirm() {
    42	        requireStatus("confirm", PENDING);
    43	        return withStatus(CONFIRMED, total, refund);
    44	    }
    45	
    46	    public Reservation startStay() {
    47	        requireStatus("check in", CONFIRMED);
    48	        return withStatus(CHECKED_IN, amountPaid, refund);
    49	    }
    50	
    51	    public Reservation endStay() {
    52	        requireStatus("check out", CHECKED_IN);
    53	        return withStatus(CHECKED_OUT, amountPaid, refund);
    54	    }
    55	
    56	    public Reservation cancel() {
    57	        requireStatus("cancel", PENDING, CONFIRMED);
    58	        return withStatus(CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
    59	    }
    60	
    61	    private void requireStatus(String operation, ReservationStatus... allowed) {
    62	        for (ReservationStatus s : allowed) {
    63	            if (status == s) {
    64	                return;
    65	            }
    66	        }
    67	        throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    68	                "Cannot " + operation + " a reservation with status " + status);
    69	    }
