     8	/**
     9	 * The one place that decides how every report looks as CSV: title line, header, rows and total.
    10	 * A change to the layout of all reports (such as a closing line with the issue date) goes here.
    11	 */
    12	public final class CsvFormat {
    13	    private CsvFormat() {
    14	    }
    15	
    16	    public static String render(ReportTable table) {
    17	        StringBuilder sb = new StringBuilder();
    18	        line(sb, List.of(Pousada.NAME, table.name(), table.period()));
    19	        line(sb, table.header());
    20	        table.rows().forEach(row -> line(sb, row));
    21	        line(sb, table.total());
    22	        return sb.toString();
    23	    }
    24	
    25	    private static void line(StringBuilder sb, List<String> cells) {
    26	        sb.append(cells.stream().map(CsvFormat::escape).collect(Collectors.joining(","))).append('\n');
    27	    }
    28	
    29	    private static String escape(String cell) {
    30	        if (cell.contains(",") || cell.contains("\"") || cell.contains("\n")) {
    31	            return '"' + cell.replace("\"", "\"\"") + '"';
    32	        }
    33	        return cell;
    34	    }
